CREATE TABLE users (
  user_id      BIGINT PRIMARY KEY,
  handle       TEXT NOT NULL UNIQUE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE follows (
  follower_id  BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  followee_id  BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (follower_id, followee_id),
  CHECK (follower_id <> followee_id)
);

-- Serves: who follows B, newest first, without touching the heap.
CREATE INDEX follows_followee_created_idx
  ON follows (followee_id, created_at DESC, follower_id);

-- Optional covering variant for: who does A follow, newest first.
CREATE INDEX follows_follower_created_idx
  ON follows (follower_id, created_at DESC, followee_id);

CREATE TABLE user_counters (
  user_id        BIGINT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,
  followers_cnt  BIGINT NOT NULL DEFAULT 0,
  following_cnt  BIGINT NOT NULL DEFAULT 0,
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Correct counter maintenance: only count real state changes.
-- In one transaction (pseudo-logic, Postgres syntax):
BEGIN;
INSERT INTO follows (follower_id, followee_id)
VALUES ($a, $b) ON CONFLICT DO NOTHING;
-- GET DIAGNOSTICS rowcount, or check RETURNING in app code.
-- Only when a row was actually inserted:
INSERT INTO user_counters (user_id, followers_cnt, following_cnt)
VALUES ($b, 1, 0), ($a, 0, 1)
ON CONFLICT (user_id) DO UPDATE SET
  followers_cnt = user_counters.followers_cnt + CASE WHEN user_counters.user_id = $b THEN 1 ELSE 0 END,
  following_cnt = user_counters.following_cnt + CASE WHEN user_counters.user_id = $a THEN 1 ELSE 0 END;
COMMIT;
